UPDATE POST
   SET title = #{title}
     , contents = #{contents}
     , category_no = #{categoryNo}
     , update_time = #{updateTime}
 WHERE no = #{no}
   AND user_no = #{userNo}
   AND delete_time IS NULL

UPDATE POST
   SET delete_time = #{deleteTime}
 WHERE no = #{no}
   AND delete_time IS NULL
